--
-- 20261105000003_lock_tenant_key.sql
-- Roadmap S0-03 (DB-01, SECF-10, SECF-09, DB-22, SECF-11): the tenant key
-- (profiles.hospital_id), activation and role-bearing data are set only by the
-- server, and every onboarding path derives the tenant from something the server
-- verified (an invitation token, a patient record, a brand-new hospital).
--
--   A. profiles        UPDATE policy gets an explicit WITH CHECK; INSERT limited
--                      to authenticated callers. The column guard is S0-10's
--                      profiles_guard_privileged_columns trigger (20261105000002,
--                      REQUIRED, not duplicated here); this file adds a small
--                      companion guard for the ABAC columns it does not list.
--   B. secrets         profiles.security_question/security_answer move to
--                      public.profile_security_answers (bcrypt hash, service role
--                      only) and are dropped from profiles; legacy
--                      profiles.two_factor_secret/backup_codes move to a
--                      service-role-only archive and are dropped (DB-22, SECF-11).
--   C. role tables     client-side role self-assignment policies on user_roles
--                      and the permissive FOR ALL policy on staff_invitations are
--                      dropped (SECF-09); admin-only invitation management.
--   D. onboarding RPCs service-role only, called by edge functions:
--                        create_hospital_with_admin  (create-hospital-admin)
--                        accept_staff_invitation     (accept-invitation-signup)
--                        verify_patient_claim + register_patient (register-patient)
--                      The broken register_patient (FUNC-01) and the
--                      oldest-hospital fallback ensure_patient_record_for_user
--                      (DB-01) are dropped; assign_patient_role is revoked.
--
-- Idempotent: IF [NOT] EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS then CREATE,
-- or guarded DO blocks. Applying it twice is a no-op.
--
-- Prerequisites (live schema): auth.users, auth.uid(); public.profiles,
-- public.user_roles, public.hospitals, public.patients, public.staff_invitations;
-- public.has_role(uuid, app_role), public.user_belongs_to_hospital(uuid, uuid);
-- pgcrypto in schema "extensions" (Supabase default); and
-- public.profiles_guard_privileged_columns() with its trigger on profiles
-- (pending migration 20261105000002, which must be applied first).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 0. Prerequisites: fail loudly instead of half-applying.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  missing text[] := ARRAY[]::text[];
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['auth.users', 'public.profiles', 'public.user_roles', 'public.hospitals',
                           'public.patients', 'public.staff_invitations'] LOOP
    IF to_regclass(t) IS NULL THEN missing := missing || t; END IF;
  END LOOP;
  FOREACH t IN ARRAY ARRAY['auth.uid()', 'public.has_role(uuid,public.app_role)',
                           'public.user_belongs_to_hospital(uuid,uuid)',
                           'extensions.crypt(text,text)', 'extensions.gen_salt(text,integer)',
                           'extensions.digest(text,text)',
                           'public.profiles_guard_privileged_columns()'] LOOP
    IF to_regprocedure(t) IS NULL THEN missing := missing || ('function ' || t); END IF;
  END LOOP;
  IF to_regclass('public.profiles') IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM pg_trigger
        WHERE tgrelid = 'public.profiles'::regclass
          AND tgname = 'profiles_guard_privileged_columns'
          AND NOT tgisinternal) THEN
    missing := missing || 'trigger profiles_guard_privileged_columns on public.profiles (apply 20261105000002 first)'::text;
  END IF;
  IF array_length(missing, 1) IS NOT NULL THEN
    RAISE EXCEPTION 'lock_tenant_key: missing prerequisites: %', array_to_string(missing, ', ');
  END IF;
END
$$;

-- =============================================================================
-- A. profiles: row ownership policies (the column guard is S0-10's trigger)
-- =============================================================================
-- Without WITH CHECK PostgreSQL reuses USING for the new row, so this changes
-- nothing on its own; it makes the intent explicit and limits the policy to
-- authenticated callers. Which COLUMNS a user may change is decided by
-- profiles_guard_privileged_columns (20261105000002): hospital_id, is_active,
-- is_staff, role, two_factor_*, failed_login_attempts, locked_until, id, user_id.
DROP POLICY IF EXISTS "Users can update their own profile" ON public.profiles;
DROP POLICY IF EXISTS profiles_update_own ON public.profiles;
CREATE POLICY profiles_update_own ON public.profiles
  FOR UPDATE TO authenticated
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

-- First profile row for a self-signed-up user (AuthContext.signup,
-- AccountSetupPage). The S0-10 trigger rejects a client INSERT that sets
-- hospital_id, is_staff, two_factor_* or lockout columns, so the row starts
-- without a tenant; the onboarding RPCs below assign one.
DROP POLICY IF EXISTS "Users can insert their own profile" ON public.profiles;
DROP POLICY IF EXISTS profiles_insert_own ON public.profiles;
CREATE POLICY profiles_insert_own ON public.profiles
  FOR INSERT TO authenticated
  WITH CHECK (user_id = auth.uid());

-- Companion guard for privilege-bearing ABAC attributes that the S0-10 trigger
-- does not list. Same caller rule: only anon/authenticated (PostgREST) callers
-- are restricted; service_role, postgres and SECURITY DEFINER functions are not.
-- Columns that do not exist live are ignored (to_jsonb).
CREATE OR REPLACE FUNCTION public.profiles_guard_abac_columns()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_new jsonb := to_jsonb(NEW);
  v_old jsonb;
  c     text;
  v_protected constant text[] := ARRAY['clearance_level', 'sensitivity_level', 'seniority'];
BEGIN
  IF current_user NOT IN ('anon', 'authenticated') THEN
    RETURN NEW;
  END IF;
  v_old := CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END;
  FOREACH c IN ARRAY v_protected LOOP
    IF TG_OP = 'INSERT' THEN
      -- A column default is fine; an explicit value from the client is not
      -- distinguishable from it, so only reject values that differ from NULL
      -- when the column has no default.
      CONTINUE WHEN NOT (v_new ? c) OR (v_new -> c) = 'null'::jsonb;
      CONTINUE WHEN EXISTS (
        SELECT 1 FROM pg_attribute a
         WHERE a.attrelid = TG_RELID AND a.attname = c AND a.atthasdef);
      RAISE EXCEPTION 'profiles.% is managed by the server', c USING ERRCODE = '42501';
    ELSIF (v_new -> c) IS DISTINCT FROM (v_old -> c) THEN
      RAISE EXCEPTION 'profiles.% is managed by the server and cannot be changed by the user', c
        USING ERRCODE = '42501';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS profiles_guard_abac_columns ON public.profiles;
CREATE TRIGGER profiles_guard_abac_columns
  BEFORE INSERT OR UPDATE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.profiles_guard_abac_columns();

-- =============================================================================
-- B. Secrets out of profiles (DB-22, SECF-11)
-- =============================================================================
-- profiles is readable hospital-wide (profiles SELECT policy) and the client
-- selects profiles.*, so a column REVOKE would break select('*'). The values
-- move to service-role-only tables and the columns are dropped.

-- B1. Security question answers: kept only as a bcrypt hash of
-- lower(btrim(answer)). Nothing verifies them today (SECF-11); the hash keeps
-- a future server-side verifier possible without keeping plaintext. Drop the
-- table if product decides the feature is gone for good.
CREATE TABLE IF NOT EXISTS public.profile_security_answers (
  user_id     uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  question    text,
  answer_hash text NOT NULL,
  hash_scheme text NOT NULL DEFAULT 'bcrypt(lower(btrim(answer)))',
  migrated_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.profile_security_answers IS
  'S0-03 (SECF-11): bcrypt hashes of the legacy security answers moved out of profiles. Service role only.';
ALTER TABLE public.profile_security_answers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.profile_security_answers FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profile_security_answers TO service_role;

-- B2. Legacy custom-2FA artefacts. Nothing reads these columns (the custom
-- TOTP functions used two_factor_secrets and are retired by S0-10). They are
-- archived, not destroyed, so an operator can verify and then drop the archive.
CREATE TABLE IF NOT EXISTS public.profiles_legacy_2fa_archive (
  user_id           uuid PRIMARY KEY,
  two_factor_secret text,
  backup_codes      text[],
  archived_at       timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.profiles_legacy_2fa_archive IS
  'S0-03 (DB-22): profiles.two_factor_secret/backup_codes moved out of the client-readable table. Service role only. Drop after review.';
ALTER TABLE public.profiles_legacy_2fa_archive ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.profiles_legacy_2fa_archive FROM PUBLIC, anon, authenticated;
GRANT SELECT, DELETE ON public.profiles_legacy_2fa_archive TO service_role;

-- Fallback guard, used only if a column cannot be dropped because a view
-- depends on it: the column is emptied and must stay NULL.
CREATE OR REPLACE FUNCTION public.profiles_reject_legacy_secret_columns()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_new jsonb := to_jsonb(NEW);
  c text;
BEGIN
  FOREACH c IN ARRAY ARRAY['security_answer', 'two_factor_secret', 'backup_codes'] LOOP
    IF (v_new ? c) AND (v_new -> c) <> 'null'::jsonb THEN
      RAISE EXCEPTION 'profiles.% is no longer stored in profiles', c USING ERRCODE = '42501';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;

DO $$
DECLARE
  v_has_answer   boolean;
  v_has_question boolean;
  v_has_secret   boolean;
  v_has_codes    boolean;
  v_fallback     boolean := false;
  c text;
BEGIN
  SELECT
    bool_or(attname = 'security_answer'), bool_or(attname = 'security_question'),
    bool_or(attname = 'two_factor_secret'), bool_or(attname = 'backup_codes')
  INTO v_has_answer, v_has_question, v_has_secret, v_has_codes
  FROM pg_attribute
  WHERE attrelid = 'public.profiles'::regclass AND attnum > 0 AND NOT attisdropped;

  IF coalesce(v_has_answer, false) THEN
    EXECUTE format($q$
      INSERT INTO public.profile_security_answers (user_id, question, answer_hash)
      SELECT p.user_id, %s,
             extensions.crypt(lower(btrim(p.security_answer)), extensions.gen_salt('bf', 10))
        FROM public.profiles p
       WHERE p.security_answer IS NOT NULL AND btrim(p.security_answer) <> ''
         AND EXISTS (SELECT 1 FROM auth.users u WHERE u.id = p.user_id)
      ON CONFLICT (user_id) DO NOTHING$q$,
      CASE WHEN coalesce(v_has_question, false) THEN 'p.security_question' ELSE 'NULL::text' END);
  END IF;

  IF coalesce(v_has_secret, false) OR coalesce(v_has_codes, false) THEN
    EXECUTE format($q$
      INSERT INTO public.profiles_legacy_2fa_archive (user_id, two_factor_secret, backup_codes)
      SELECT p.user_id, %s, %s FROM public.profiles p
       WHERE %s
      ON CONFLICT (user_id) DO NOTHING$q$,
      CASE WHEN coalesce(v_has_secret, false) THEN 'p.two_factor_secret' ELSE 'NULL::text' END,
      CASE WHEN coalesce(v_has_codes, false) THEN 'p.backup_codes' ELSE 'NULL::text[]' END,
      concat_ws(' OR ',
        CASE WHEN coalesce(v_has_secret, false) THEN 'p.two_factor_secret IS NOT NULL' END,
        CASE WHEN coalesce(v_has_codes, false) THEN 'p.backup_codes IS NOT NULL' END));
  END IF;

  FOREACH c IN ARRAY ARRAY['security_answer', 'security_question', 'two_factor_secret', 'backup_codes'] LOOP
    CONTINUE WHEN NOT EXISTS (
      SELECT 1 FROM pg_attribute
       WHERE attrelid = 'public.profiles'::regclass AND attname = c AND attnum > 0 AND NOT attisdropped);
    BEGIN
      EXECUTE format('ALTER TABLE public.profiles DROP COLUMN %I', c);
    EXCEPTION WHEN dependent_objects_still_exist THEN
      -- A view uses the column. Empty it instead and keep it empty.
      IF c <> 'security_question' THEN
        EXECUTE format('UPDATE public.profiles SET %I = NULL WHERE %I IS NOT NULL', c, c);
        v_fallback := true;
      END IF;
      RAISE WARNING 'lock_tenant_key: profiles.% has dependent objects; it was emptied, not dropped. Drop it after removing the dependency.', c;
    END;
  END LOOP;

  IF v_fallback THEN
    EXECUTE 'DROP TRIGGER IF EXISTS profiles_reject_legacy_secret_columns ON public.profiles';
    EXECUTE 'CREATE TRIGGER profiles_reject_legacy_secret_columns BEFORE INSERT OR UPDATE ON public.profiles '
            'FOR EACH ROW EXECUTE FUNCTION public.profiles_reject_legacy_secret_columns()';
  END IF;
END
$$;

-- =============================================================================
-- C. Role-bearing tables: no client-side self-assignment (SECF-09)
-- =============================================================================
-- user_roles: a new hospital's first admin role is created by
-- create_hospital_with_admin, invited roles by accept_staff_invitation and the
-- patient role by register_patient. These client policies let a user grant
-- themselves a role:
--   "Users can insert their own initial role"   any role (misc.sql)
--   "Users can insert initial admin role for new hospital"  admin of any
--       hospital that has no roles yet
--   "User roles hospital scoped"  FOR ALL with USING only, so its implicit
--       WITH CHECK (user_id = auth.uid()) admits any self-inserted role, and it
--       lets any same-hospital staff member rewrite colleagues' roles.
-- Admin management stays with "Admins can manage roles in their hospital".
DROP POLICY IF EXISTS "Users can insert their own initial role" ON public.user_roles;
DROP POLICY IF EXISTS "Users can insert initial admin role for new hospital" ON public.user_roles;
DROP POLICY IF EXISTS "User roles hospital scoped" ON public.user_roles;
-- Reading one's own roles must keep working (AuthContext) whatever else is live.
DROP POLICY IF EXISTS user_roles_select_own ON public.user_roles;
CREATE POLICY user_roles_select_own ON public.user_roles
  FOR SELECT TO authenticated
  USING (user_id = auth.uid());

-- staff_invitations: invitations carry the role and the tenant an invitee
-- receives, so only an admin of that hospital may see or write them. The
-- "hospital scoped" FOR ALL policy (security_compliance.sql) let any member
-- mint admin invitations and read every token.
DROP POLICY IF EXISTS "Staff invitations hospital scoped" ON public.staff_invitations;
DROP POLICY IF EXISTS "Anyone can view invitation by token" ON public.staff_invitations;
DROP POLICY IF EXISTS staff_invitations_admin_manage ON public.staff_invitations;
CREATE POLICY staff_invitations_admin_manage ON public.staff_invitations
  FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin'::public.app_role)
         AND public.user_belongs_to_hospital(auth.uid(), hospital_id))
  WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role)
              AND public.user_belongs_to_hospital(auth.uid(), hospital_id));
ALTER TABLE public.staff_invitations ENABLE ROW LEVEL SECURITY;

-- =============================================================================
-- D. Onboarding RPCs (service role only; the edge functions verify the caller)
-- =============================================================================

-- D1. New hospital + first admin. Called by create-hospital-admin with the
-- caller's verified user id. Only for an account with no tenant and no roles:
-- it can never move an existing member to another hospital.
CREATE OR REPLACE FUNCTION public.create_hospital_with_admin(
  p_user_id UUID,
  p_name TEXT,
  p_address TEXT,
  p_city TEXT,
  p_state TEXT,
  p_zip TEXT,
  p_phone TEXT,
  p_email TEXT,
  p_license_number TEXT
) RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_hospital_id UUID;
  v_email       TEXT;
  v_meta        JSONB;
  v_profile     public.profiles%ROWTYPE;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'create_hospital_with_admin: user id is required' USING ERRCODE = '22004';
  END IF;
  IF coalesce(btrim(p_name), '') = '' THEN
    RAISE EXCEPTION 'create_hospital_with_admin: hospital name is required' USING ERRCODE = '22023';
  END IF;

  SELECT u.email, coalesce(u.raw_user_meta_data, '{}'::jsonb) INTO v_email, v_meta
    FROM auth.users u WHERE u.id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'create_hospital_with_admin: user not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:' || p_user_id::text, 0));

  IF EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = p_user_id) THEN
    RAISE EXCEPTION 'create_hospital_with_admin: account already has a role' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_profile FROM public.profiles WHERE user_id = p_user_id FOR UPDATE;
  IF FOUND AND v_profile.hospital_id IS NOT NULL THEN
    RAISE EXCEPTION 'create_hospital_with_admin: account already belongs to a hospital' USING ERRCODE = '42501';
  END IF;
  IF NOT FOUND THEN
    IF coalesce(v_email, '') = '' THEN
      RAISE EXCEPTION 'create_hospital_with_admin: account has no email' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.profiles (user_id, email, first_name, last_name)
    VALUES (p_user_id, v_email,
            coalesce(nullif(btrim(v_meta ->> 'first_name'), ''), 'User'),
            coalesce(nullif(btrim(v_meta ->> 'last_name'), ''), 'Account'));
  END IF;

  INSERT INTO public.hospitals (name, address, city, state, zip, phone, email, license_number)
  VALUES (btrim(p_name), NULLIF(p_address, ''), NULLIF(p_city, ''), NULLIF(p_state, ''),
          NULLIF(p_zip, ''), NULLIF(p_phone, ''), NULLIF(p_email, ''),
          NULLIF(btrim(coalesce(p_license_number, '')), ''))
  RETURNING id INTO v_hospital_id;

  UPDATE public.profiles SET hospital_id = v_hospital_id WHERE user_id = p_user_id;

  INSERT INTO public.user_roles (user_id, role, hospital_id)
  VALUES (p_user_id, 'admin', v_hospital_id);

  RETURN v_hospital_id;
END;
$$;

-- D2. Staff invitation acceptance. Called by accept-invitation-signup after it
-- created the invitee's auth user. The tenant and role come from the
-- invitation row only; the account email must be the invited email.
CREATE OR REPLACE FUNCTION public.accept_staff_invitation(
  p_token TEXT,
  p_user_id UUID,
  p_first_name TEXT,
  p_last_name TEXT,
  p_email TEXT
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_invitation public.staff_invitations%ROWTYPE;
  v_auth_email TEXT;
  v_existing_hospital UUID;
BEGIN
  IF p_user_id IS NULL OR coalesce(p_token, '') = '' THEN
    RAISE EXCEPTION 'accept_staff_invitation: token and user id are required' USING ERRCODE = '22004';
  END IF;

  SELECT * INTO v_invitation
    FROM public.staff_invitations
   WHERE token::text = p_token
     AND status = 'pending'
     AND expires_at > now()
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid or expired invitation' USING ERRCODE = 'P0002';
  END IF;

  SELECT email INTO v_auth_email FROM auth.users WHERE id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accept_staff_invitation: user not found' USING ERRCODE = 'P0002';
  END IF;
  IF lower(btrim(coalesce(v_auth_email, ''))) <> lower(btrim(v_invitation.email))
     OR lower(btrim(coalesce(p_email, ''))) <> lower(btrim(v_invitation.email)) THEN
    RAISE EXCEPTION 'accept_staff_invitation: account email does not match the invitation' USING ERRCODE = '42501';
  END IF;

  SELECT hospital_id INTO v_existing_hospital FROM public.profiles WHERE user_id = p_user_id;
  IF v_existing_hospital IS NOT NULL AND v_existing_hospital <> v_invitation.hospital_id THEN
    RAISE EXCEPTION 'accept_staff_invitation: account already belongs to another hospital' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.profiles (user_id, first_name, last_name, email, hospital_id)
  VALUES (p_user_id, p_first_name, p_last_name, v_invitation.email, v_invitation.hospital_id)
  ON CONFLICT (user_id) DO UPDATE SET
    first_name  = EXCLUDED.first_name,
    last_name   = EXCLUDED.last_name,
    email       = EXCLUDED.email,
    hospital_id = EXCLUDED.hospital_id;

  IF NOT EXISTS (SELECT 1 FROM public.user_roles
                  WHERE user_id = p_user_id AND role = v_invitation.role
                    AND hospital_id IS NOT DISTINCT FROM v_invitation.hospital_id) THEN
    INSERT INTO public.user_roles (user_id, role, hospital_id)
    VALUES (p_user_id, v_invitation.role, v_invitation.hospital_id);
  END IF;

  UPDATE public.staff_invitations
     SET status = 'accepted', accepted_at = now()
   WHERE id = v_invitation.id;

  RETURN jsonb_build_object(
    'invitation_id', v_invitation.id,
    'hospital_id', v_invitation.hospital_id,
    'role', v_invitation.role);
END;
$$;

-- D3. Patient self-registration = claiming an existing, staff-created patient
-- record. The hospital is the record's hospital; the client never names a
-- hospital id. The claimant must give the hospital code (license number), the
-- MRN, date of birth and last name on the record, and register with the email
-- address on the record (Supabase then confirms they own it). Records without an
-- email cannot be claimed; reception adds one first.

-- Old register_patient (FUNC-01: targets a roles table / profile_id column that
-- do not exist, trusts p_user_id, executable by authenticated) and every other
-- overload of that name except the one created below.
DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure AS sig
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public' AND p.proname = 'register_patient'
       AND pg_get_function_identity_arguments(p.oid)
           <> 'p_user_id uuid, p_hospital_code text, p_mrn text, p_date_of_birth date, p_last_name text, p_email text'
  LOOP
    EXECUTE format('DROP FUNCTION %s', r.sig);
  END LOOP;
END
$$;

-- DB-01: SECURITY DEFINER, executable by authenticated, any p_user_id, and it
-- fell back to the oldest hospital (a tenant-id oracle). Nothing calls it.
DROP FUNCTION IF EXISTS public.ensure_patient_record_for_user(
  UUID, TEXT, TEXT, TEXT, TEXT, DATE, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT[], TEXT[], TEXT, TEXT, TEXT);

-- Superseded by register_patient; a role without a record only confuses the
-- portal. Kept for the service role, no longer callable by clients.
DO $$
BEGIN
  IF to_regprocedure('public.assign_patient_role(uuid)') IS NOT NULL THEN
    REVOKE ALL ON FUNCTION public.assign_patient_role(uuid) FROM PUBLIC, anon, authenticated;
    GRANT EXECUTE ON FUNCTION public.assign_patient_role(uuid) TO service_role;
  END IF;
END
$$;

CREATE TABLE IF NOT EXISTS public.patient_claim_attempts (
  id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  client_key   text NOT NULL,
  hospital_id  uuid,
  record_key   text NOT NULL,
  succeeded    boolean NOT NULL,
  attempted_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS patient_claim_attempts_client_idx ON public.patient_claim_attempts (client_key, attempted_at DESC);
CREATE INDEX IF NOT EXISTS patient_claim_attempts_record_idx ON public.patient_claim_attempts (record_key, attempted_at DESC);
CREATE INDEX IF NOT EXISTS patient_claim_attempts_hospital_idx ON public.patient_claim_attempts (hospital_id, attempted_at DESC);
COMMENT ON TABLE public.patient_claim_attempts IS
  'S0-03: patient self-registration attempts for throttling. record_key = sha256(hospital|MRN), client_key = hash of the caller IP. Service role only.';
ALTER TABLE public.patient_claim_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.patient_claim_attempts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, DELETE ON public.patient_claim_attempts TO service_role;

-- S0-03 type fix: the RPC parameters are date, and patients.date_of_birth must
-- be compared as a date. When the column is text (as a text-typed fixture
-- assumes; types.ts shows string for text, date and timestamptz alike), this
-- converts the stored value. Returns NULL (no match, no error) for NULL, for
-- anything that is not YYYY-MM-DD, and for impossible dates such as 1980-02-30,
-- so one bad row cannot make every claim fail. Immutable, no table access, not
-- callable by clients. A DATE overload follows for a date-typed column.
CREATE OR REPLACE FUNCTION public.patient_dob_as_date(p_text TEXT)
RETURNS DATE
LANGUAGE plpgsql
IMMUTABLE
SET search_path = pg_catalog
AS $$
BEGIN
  IF p_text IS NULL OR p_text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RETURN NULL;
  END IF;
  RETURN p_text::date;
EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN
  RETURN NULL;
END
$$;
REVOKE ALL ON FUNCTION public.patient_dob_as_date(TEXT) FROM PUBLIC, anon, authenticated;

-- The same comparison also works when the live column is DATE (the repository
-- migrations declare it DATE; types.ts shows string for both). The overload
-- resolves by the column's own type, so no cast is applied to a DATE value.
CREATE OR REPLACE FUNCTION public.patient_dob_as_date(p_value DATE)
RETURNS DATE
LANGUAGE sql
IMMUTABLE
SET search_path = pg_catalog
AS $$ SELECT p_value $$;
REVOKE ALL ON FUNCTION public.patient_dob_as_date(DATE) FROM PUBLIC, anon, authenticated;

-- Matching rule shared by both RPCs. Not SECURITY DEFINER: it runs with the
-- privileges of the definer functions that call it.
CREATE OR REPLACE FUNCTION public.patient_claim_candidates(
  p_hospital_code TEXT, p_mrn TEXT, p_date_of_birth DATE, p_last_name TEXT, p_email TEXT)
RETURNS TABLE (patient_id UUID, hospital_id UUID)
LANGUAGE sql
STABLE
SET search_path = public, pg_temp
AS $$
  SELECT p.id, p.hospital_id
    FROM public.patients p
    JOIN public.hospitals h ON h.id = p.hospital_id
   WHERE nullif(btrim(p_hospital_code), '') IS NOT NULL
     AND lower(btrim(h.license_number)) = lower(btrim(p_hospital_code))
     AND upper(regexp_replace(p.mrn, '\s', '', 'g')) = upper(regexp_replace(coalesce(p_mrn, ''), '\s', '', 'g'))
     AND public.patient_dob_as_date(p.date_of_birth) = p_date_of_birth
     AND lower(btrim(p.last_name)) = lower(btrim(coalesce(p_last_name, '')))
     AND p.email IS NOT NULL
     AND lower(btrim(p.email)) = lower(btrim(coalesce(p_email, '')))
     AND p.user_id IS NULL
     AND coalesce(p.is_active, true)
$$;

-- Pre-check with throttling, called by register-patient BEFORE it creates the
-- auth user (so a failed claim leaves no account behind). Limits per hour:
-- 10 failures per client, 5 per (hospital, MRN), 50 per hospital.
-- Returns {"status":"ok"} | {"status":"invalid"} | {"status":"locked","retry_after_seconds":n}.
CREATE OR REPLACE FUNCTION public.verify_patient_claim(
  p_client_key TEXT, p_hospital_code TEXT, p_mrn TEXT, p_date_of_birth DATE,
  p_last_name TEXT, p_email TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  c_window       constant interval := interval '1 hour';
  v_hospital_id  uuid;
  v_record_key   text;
  v_client_key   text := coalesce(nullif(btrim(p_client_key), ''), 'unknown');
  v_oldest       timestamptz;
  v_n            int;
BEGIN
  SELECT h.id INTO v_hospital_id
    FROM public.hospitals h
   WHERE nullif(btrim(p_hospital_code), '') IS NOT NULL
     AND lower(btrim(h.license_number)) = lower(btrim(p_hospital_code))
   LIMIT 1;

  v_record_key := encode(extensions.digest(
    coalesce(v_hospital_id::text, '-') || '|' || upper(regexp_replace(coalesce(p_mrn, ''), '\s', '', 'g')),
    'sha256'), 'hex');

  PERFORM pg_advisory_xact_lock(hashtextextended('patient_claim:' || v_record_key, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('patient_claim_client:' || v_client_key, 0));

  DELETE FROM public.patient_claim_attempts WHERE attempted_at < clock_timestamp() - interval '1 day';

  SELECT count(*), min(attempted_at) INTO v_n, v_oldest FROM public.patient_claim_attempts
   WHERE client_key = v_client_key AND NOT succeeded AND attempted_at > clock_timestamp() - c_window;
  IF v_n < 10 THEN
    SELECT count(*), min(attempted_at) INTO v_n, v_oldest FROM public.patient_claim_attempts
     WHERE record_key = v_record_key AND NOT succeeded AND attempted_at > clock_timestamp() - c_window;
    IF v_n >= 5 THEN v_n := 10; END IF;
  END IF;
  IF v_n < 10 AND v_hospital_id IS NOT NULL THEN
    SELECT count(*), min(attempted_at) INTO v_n, v_oldest FROM public.patient_claim_attempts
     WHERE hospital_id = v_hospital_id AND NOT succeeded AND attempted_at > clock_timestamp() - c_window;
    v_n := CASE WHEN v_n >= 50 THEN 10 ELSE 0 END;
  END IF;
  IF v_n >= 10 THEN
    RETURN jsonb_build_object('status', 'locked', 'retry_after_seconds',
      greatest(1, ceil(extract(epoch FROM (v_oldest + c_window - clock_timestamp())))::int));
  END IF;

  SELECT count(*) INTO v_n
    FROM public.patient_claim_candidates(p_hospital_code, p_mrn, p_date_of_birth, p_last_name, p_email);

  INSERT INTO public.patient_claim_attempts (client_key, hospital_id, record_key, succeeded)
  VALUES (v_client_key, v_hospital_id, v_record_key, v_n = 1);

  RETURN jsonb_build_object('status', CASE WHEN v_n = 1 THEN 'ok' ELSE 'invalid' END);
END;
$$;

-- Link a freshly created auth user to the matching record, atomically:
-- patients.user_id, the profile (tenant = the record's hospital, is_staff false)
-- and the patient role. Re-verifies the match under a row lock.
CREATE OR REPLACE FUNCTION public.register_patient(
  p_user_id UUID, p_hospital_code TEXT, p_mrn TEXT, p_date_of_birth DATE,
  p_last_name TEXT, p_email TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_auth_email  text;
  v_patient     public.patients%ROWTYPE;
  v_ids         uuid[];
  v_profile_hid uuid;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'register_patient: user id is required' USING ERRCODE = '22004';
  END IF;

  SELECT email INTO v_auth_email FROM auth.users WHERE id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'register_patient: user not found' USING ERRCODE = 'P0002';
  END IF;
  IF lower(btrim(coalesce(v_auth_email, ''))) <> lower(btrim(coalesce(p_email, ''))) THEN
    RAISE EXCEPTION 'register_patient: account email does not match' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:' || p_user_id::text, 0));

  IF EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = p_user_id)
     OR EXISTS (SELECT 1 FROM public.patients WHERE user_id = p_user_id) THEN
    RAISE EXCEPTION 'register_patient: account is already registered' USING ERRCODE = '42501';
  END IF;
  SELECT hospital_id INTO v_profile_hid FROM public.profiles WHERE user_id = p_user_id;
  IF v_profile_hid IS NOT NULL THEN
    RAISE EXCEPTION 'register_patient: account already belongs to a hospital' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(c.patient_id) INTO v_ids
    FROM public.patient_claim_candidates(p_hospital_code, p_mrn, p_date_of_birth, p_last_name, p_email) c;
  IF coalesce(array_length(v_ids, 1), 0) <> 1 THEN
    RAISE EXCEPTION 'register_patient: no matching patient record' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_patient FROM public.patients WHERE id = v_ids[1] FOR UPDATE;
  IF v_patient.user_id IS NOT NULL THEN  -- claimed concurrently
    RAISE EXCEPTION 'register_patient: no matching patient record' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.patients SET user_id = p_user_id WHERE id = v_patient.id;

  INSERT INTO public.profiles (user_id, email, first_name, last_name, hospital_id, is_staff)
  VALUES (p_user_id, v_auth_email, v_patient.first_name, v_patient.last_name, v_patient.hospital_id, false)
  ON CONFLICT (user_id) DO UPDATE SET hospital_id = EXCLUDED.hospital_id, is_staff = false;

  INSERT INTO public.user_roles (user_id, role, hospital_id)
  VALUES (p_user_id, 'patient', v_patient.hospital_id);

  RETURN jsonb_build_object('patient_id', v_patient.id, 'hospital_id', v_patient.hospital_id);
END;
$$;

-- Grants: none of these is callable by anon/authenticated. Supabase's default
-- privileges grant EXECUTE on new public functions to both, so revoke explicitly.
REVOKE ALL ON FUNCTION public.create_hospital_with_admin(UUID, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.accept_staff_invitation(TEXT, UUID, TEXT, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.patient_claim_candidates(TEXT, TEXT, DATE, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.verify_patient_claim(TEXT, TEXT, TEXT, DATE, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.register_patient(UUID, TEXT, TEXT, DATE, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.profiles_guard_abac_columns() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.profiles_reject_legacy_secret_columns() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_hospital_with_admin(UUID, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.accept_staff_invitation(TEXT, UUID, TEXT, TEXT, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.patient_claim_candidates(TEXT, TEXT, DATE, TEXT, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.verify_patient_claim(TEXT, TEXT, TEXT, DATE, TEXT, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.register_patient(UUID, TEXT, TEXT, DATE, TEXT, TEXT) TO service_role;

COMMENT ON FUNCTION public.create_hospital_with_admin(UUID, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) IS
  'S0-03: new hospital + first admin for an account with no hospital and no roles. Service role only (create-hospital-admin).';
COMMENT ON FUNCTION public.accept_staff_invitation(TEXT, UUID, TEXT, TEXT, TEXT) IS
  'S0-03: tenant and role from the invitation row; account email must equal the invited email. Service role only (accept-invitation-signup).';
COMMENT ON FUNCTION public.verify_patient_claim(TEXT, TEXT, TEXT, DATE, TEXT, TEXT) IS
  'S0-03: throttled pre-check for patient self-registration. Service role only (register-patient).';
COMMENT ON FUNCTION public.register_patient(UUID, TEXT, TEXT, DATE, TEXT, TEXT) IS
  'S0-03 (FUNC-01, DB-01): links a new auth user to a matching unclaimed patient record; tenant from the record. Service role only (register-patient).';

COMMIT;
